Unit Test Code:
#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_inorder_null_root(void) {
    // Setup: root is NULL to trigger the path where (root != NULL) is false
    struct node* root = NULL;

    // Test: call inorder with NULL root
    // This should not crash and should produce no output
    // We'll capture stdout to verify nothing is printed
    stdout_capture_t* cap = capture_stdout_start();
    inorder(root);
    char* output = capture_stdout_stop(cap);

    // Assertions: output should be empty string (or NULL)
    TEST_ASSERT_NOT_NULL(output);
    TEST_ASSERT_EQUAL_STRING("", output);

    // Cleanup
    free(output);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_inorder_null_root);
    return UNITY_END();
}

